{"path": "check_matches.py", "content": """"Independent check of ./matches.json against ./log.txt.

Re-implements the README semantics with plain Python (no regex) and compares
the expected list of last-valid-dates-per-qualifying-line with the file.
"""

import json
import re
from pathlib import Path

HERE = Path(__file__).resolve().parent

OCTET = re.compile(r"^(?:25[0-5]|2[0-4][0-9]|1[0-9][0-9]|[1-9]?[0-9])$")
DATE_RE = re.compile(r"^([0-9]{4})-([0-9]{2})-([0-9]{2})$")
ALNUM = set("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz")


def valid_date(tok: str) -> bool:
    m = DATE_RE.match(tok)
    if not m:
        return False
    year, month, day = (int(g) for g in m.groups())
    if not 1 <= month <= 12:
        return False
    max_day = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1]
    return 1 <= day <= max_day


def has_ipv4(line: str) -> bool:
    """Scan for a dotted quad whose octets are 0-255 with no leading zeros and
    which is not adjacent to an alphanumeric character."""
    for m in re.finditer(r"[0-9]+(?:\.[0-9]+)+", line):
        start, end = m.span()
        if start > 0 and line[start - 1] in ALNUM:
            continue
        if end < len(line) and line[end] in ALNUM:
            continue
        parts = m.group(0).split(".")
        if len(parts) != 4:
            continue
        if all(OCTET.match(p) for p in parts):
            return True
    return False


def last_date(line: str):
    """Last calendar-valid YYYY-MM-DD token not adjacent to alphanumerics."""
    found = None
    for m in re.finditer(r"[0-9]{4}-[0-9]{2}-[0-9]{2}", line):
        start, end = m.span()
        if start > 0 and line[start - 1] in ALNUM:
            continue
        if end < len(line) and line[end] in ALNUM:
            continue
        if valid_date(m.group(0)):
            found = m.group(0)
    return found


def main() -> None:
    lines = HERE.joinpath("log.txt").read_text(encoding="utf-8").splitlines()
    expected = []
    for line in lines:
        if not has_ipv4(line):
            continue
        d = last_date(line)
        if d is not None:
            expected.append(d)

    actual = json.loads(HERE.joinpath("matches.json").read_text(encoding="utf-8"))

    print("expected:", expected)
    print("actual  :", actual)
    assert isinstance(actual, list), "matches.json must be a JSON list"
    assert all(isinstance(x, str) for x in actual), "entries must be strings"
    assert actual == expected, "MISMATCH"
    print("OK: matches.json equals independently computed expectation")


if __name__ == "__main__":
    main()
"}

